int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    array<int, 7> dp;
    dp.fill(-1);

    for (int i = 0; i < N; ++i) {
        int a, b, c, d, e, f;
        cin >> a >> b >> c >> d >> e >> f;

        array<int, 7> opposite{};
        opposite[a] = f;
        opposite[f] = a;
        opposite[b] = d;
        opposite[d] = b;
        opposite[c] = e;
        opposite[e] = c;

        array<int, 7> next;
        next.fill(-1);

        for (int bottom = 1; bottom <= 6; ++bottom) {
            int top = opposite[bottom];
            int sideMax = 0;
            for (int value = 1; value <= 6; ++value) {
                if (value != bottom && value != top) {
                    sideMax = max(sideMax, value);
                }
            }

            if (i == 0) {
                next[top] = max(next[top], sideMax);
            } else if (dp[bottom] != -1) {
                next[top] = max(next[top], dp[bottom] + sideMax);
            }
        }

        dp = next;
    }

    cout << *max_element(dp.begin() + 1, dp.end()) << '\n';
    return 0;
